#include <cstdint>
#include <map>
#include <optional>
#include <string>
#include <vector>

struct Event { std::string kind; std::uint64_t base{ 0 }; std::string name; std::uint32_t code{ 0 }; bool firstChance{ true }; };

class Tracker
{
public:
    std::string handle(const Event& e)
    {
        if (e.kind == "load") m_modules[e.base] = e.name;
        else if (e.kind == "unload") m_modules.erase(e.base);
        else if (e.kind == "exit") m_exit = e.code;
        else if (e.kind == "exception")
        {
            if (!e.firstChance) m_crashed = true;
            if (e.code != 0x80000003u) return "not-handled";
        }
        return "continue";
    }

    std::vector<std::string> modules() const
    {
        std::vector<std::string> names;
        for (const auto& [base, name] : m_modules) names.push_back(name);
        return names;
    }

    bool crashed() const { return m_crashed; }
    std::optional<std::uint32_t> exitCode() const { return m_exit; }

private:
    std::map<std::uint64_t, std::string> m_modules;     // sorted by base address
    bool m_crashed{ false };
    std::optional<std::uint32_t> m_exit;
};

unitTests:
using Names = std::vector<std::string>;
TEST("modules sorted by address") { Tracker t; t.handle({ "load", 0x7FFE0000, "kernel32.dll" }); t.handle({ "load", 0x7FF60000, "delve.exe" }); t.handle({ "load", 0x7FFF0000, "ntdll.dll" }); CHECK(t.modules() == Names({ "delve.exe", "kernel32.dll", "ntdll.dll" })); }
TEST("unloading removes a module") { Tracker t; t.handle({ "load", 0x1000, "a.dll" }); t.handle({ "load", 0x2000, "b.dll" }); t.handle({ "unload", 0x1000 }); CHECK(t.modules() == Names({ "b.dll" })); }
TEST("breakpoints continue, other exceptions are passed on")
{
    Tracker t;
    CHECK_EQ(t.handle({ "exception", 0x1234, "", 0x80000003u, true }), std::string("continue"));
    CHECK_EQ(t.handle({ "exception", 0x1234, "", 0xE06D7363u, true }), std::string("not-handled"));
    CHECK_EQ(t.handle({ "load", 0x1000, "x.dll" }), std::string("continue"));
}
TEST("first-chance exceptions are not crashes") { Tracker t; t.handle({ "exception", 0, "", 0xC0000005u, true }); CHECK(!t.crashed()); }
TEST("second-chance exceptions are crashes") { Tracker t; t.handle({ "exception", 0, "", 0xC0000005u, false }); CHECK(t.crashed()); }
TEST("exit code") { Tracker t; CHECK(!t.exitCode().has_value()); t.handle({ "exit", 0, "", 3 }); CHECK_EQ(*t.exitCode(), 3u); }

